  const exportCurrentChat = async (format: "markdown" | "pdf") => { if (!activeSession || !dbMessages.length || isExporting) return; const sessionId = activeSession.id; const title = activeSession.title; const exportMessages = dbMessages.filter((message): message is Message & { role: "user" | "assistant" } => message.role === "user" || message.role === "assistant").map((message) => ({ ...message })); setIsExporting(format); try { const input = { title, messages: exportMessages, exportedAt: new Date() }; const file = format === "markdown" ? await prepareChatMarkdown(input) : await prepareChatPdf(input); const record = await createExportMutation.mutateAsync({ sessionId, format, fileName: file.fileName, contentType: file.contentType, contentBase64: await blobToBase64(file.blob) }); if (!record?.id) throw new Error(language === "ru" ? "Экспорт не был сохранён." : "The export was not saved."); downloadPreparedChatExport(file); await utils.exports.list.invalidate(); } catch (error) { setNotice(error instanceof Error ? error.message : "Export error"); } finally { setIsExporting(null); } };
